static void run_cycle(SmartLightHUB* handle)
{
	/* Performs a 'run to completion' step. */
	if (handle->isExecuting == bool_true)
	{ 
		return;
	} 
	handle->isExecuting = bool_true;
	smartLightHUB_dispatch_next_event(handle);
	do
	{ 
		micro_step(handle);
		clear_in_events(handle);
	} while (smartLightHUB_dispatch_next_event(handle) == bool_true);
	handle->isExecuting = bool_false;
}


