static void smartlighthub_eventqueue_init(smartlighthub_eventqueue * eq, smartlighthub_event *buffer, sc_integer capacity)
{
	eq->events = buffer;
	eq->capacity = capacity;
	eq->push_index = 0;
	eq->pop_index = 0;
	eq->size = 0;
}

static sc_integer smartlighthub_eventqueue_size(smartlighthub_eventqueue * eq)
{
	return eq->size;
}

static smartlighthub_event smartlighthub_eventqueue_pop(smartlighthub_eventqueue * eq)
{
	smartlighthub_event event;
	if(smartlighthub_eventqueue_size(eq) <= 0) {
		smartlighthub_event_init(&event, SmartLightHUB_invalid_event);
	}
	else {
		event = eq->events[eq->pop_index];
		
		if(eq->pop_index < eq->capacity - 1) {
			eq->pop_index++;
		} 
		else {
			eq->pop_index = 0;
		}
		eq->size--;
	}
	return event;
}
static sc_boolean smartlighthub_eventqueue_push(smartlighthub_eventqueue * eq, smartlighthub_event ev)
{
	if(smartlighthub_eventqueue_size(eq) == eq->capacity) {
		return bool_false;
	}
	else {
		eq->events[eq->push_index] = ev;
		
		if(eq->push_index < eq->capacity - 1) {
			eq->push_index++;
		}
		else {
			eq->push_index = 0;
		}
		eq->size++;
		
		return bool_true;
	}
}
static void smartlighthub_event_init(smartlighthub_event * ev, SmartLightHUBEventID name)
{
	ev->name = name;
}

static void smartLightHUB_add_event_to_queue(smartlighthub_eventqueue * eq, SmartLightHUBEventID name)
{
	smartlighthub_event event;
	smartlighthub_event_init(&event, name);
	smartlighthub_eventqueue_push(eq, event);
}

static sc_boolean smartLightHUB_dispatch_event(SmartLightHUB* handle, const smartlighthub_event * event) {
	switch(event->name) {
		case SmartLightHUB_toggle:
		{
			handle->iface.toggle_raised = bool_true;
			return bool_true;
		}
		case SmartLightHUB_HUB_TurnONSystems:
		{
			handle->ifaceHUB.TurnONSystems_raised = bool_true;
			return bool_true;
		}
		case SmartLightHUB_HUB_TurnOFFSystems:
		{
			handle->ifaceHUB.TurnOFFSystems_raised = bool_true;
			return bool_true;
		}
		case SmartLightHUB_Network_error:
		{
			handle->ifaceNetwork.error_raised = bool_true;
			return bool_true;
		}
		case SmartLightHUB_Network_connect:
		{
			handle->ifaceNetwork.connect_raised = bool_true;
			return bool_true;
		}
		case SmartLightHUB_System1_toggle:
		{
			handle->ifaceSystem1.toggle_raised = bool_true;
			return bool_true;
		}
		case SmartLightHUB_System1_error:
		{
			handle->ifaceSystem1.error_raised = bool_true;
			return bool_true;
		}
		case SmartLightHUB_System1_working:
		{
			handle->ifaceSystem1.working_raised = bool_true;
			return bool_true;
		}
		case SmartLightHUB_System2_toggle:
		{
			handle->ifaceSystem2.toggle_raised = bool_true;
			return bool_true;
		}
		case SmartLightHUB_System2_error:
		{
			handle->ifaceSystem2.error_raised = bool_true;
			return bool_true;
		}
		case SmartLightHUB_System2_working:
		{
			handle->ifaceSystem2.working_raised = bool_true;
			return bool_true;
		}
		case SmartLightHUB_SmartLightHUB_SmartLightHubSystem_1_0_SmartLightsHUB_PowerConsumptionRegion_PowerConsumptionCalculator_time_event_0:
		{
			handle->timeEvents.smartLightHUB_SmartLightHubSystem_1_0_SmartLightsHUB_PowerConsumptionRegion_PowerConsumptionCalculator_tev0_raised = bool_true;
			return bool_true;
		}
		case SmartLightHUB_SmartLightHUB_SmartLightHubSystem_1_0_SmartLightsHUB_PowerConsumptionRegion_IOT_EnergySaverManager_time_event_0:
		{
			handle->timeEvents.smartLightHUB_SmartLightHubSystem_1_0_SmartLightsHUB_PowerConsumptionRegion_IOT_EnergySaverManager_tev0_raised = bool_true;
			return bool_true;
		}
		case SmartLightHUB_SmartLightHUB_SmartLightHubSystem_1_0_SmartLightsHUB_NetworkRegion_No_Connection_time_event_0:
		{
			handle->timeEvents.smartLightHUB_SmartLightHubSystem_1_0_SmartLightsHUB_NetworkRegion_No_Connection_tev0_raised = bool_true;
			return bool_true;
		}
		case SmartLightHUB_SmartLightHUB_SmartLightHubSystem_1_0_SmartLightsHUB_NetworkRegion_Connected_time_event_0:
		{
			handle->timeEvents.smartLightHUB_SmartLightHubSystem_1_0_SmartLightsHUB_NetworkRegion_Connected_tev0_raised = bool_true;
			return bool_true;
		}
		default:
			return bool_false;
	}
}

static smartlighthub_event smartLightHUB_get_next_event(SmartLightHUB* handle)
{
	smartlighthub_event next_event;
	smartlighthub_event_init(&next_event, SmartLightHUB_invalid_event);
	if(smartlighthub_eventqueue_size(&(handle->in_event_queue)) > 0) {
		next_event = smartlighthub_eventqueue_pop(&(handle->in_event_queue));
	}
	return next_event;
}

static sc_boolean smartLightHUB_dispatch_next_event(SmartLightHUB* handle)
{
	smartlighthub_event nextEvent;
	nextEvent = smartLightHUB_get_next_event(handle);
	return smartLightHUB_dispatch_event(handle, &nextEvent);
}

static SmartLightHUBEventID smartLightHUB_get_timed_event_name(SmartLightHUB* handle, sc_eventid evid)
{
	if(evid == &handle->timeEvents.smartLightHUB_SmartLightHubSystem_1_0_SmartLightsHUB_PowerConsumptionRegion_PowerConsumptionCalculator_tev0_raised) {
		return SmartLightHUB_SmartLightHUB_SmartLightHubSystem_1_0_SmartLightsHUB_PowerConsumptionRegion_PowerConsumptionCalculator_time_event_0;
	}
	if(evid == &handle->timeEvents.smartLightHUB_SmartLightHubSystem_1_0_SmartLightsHUB_PowerConsumptionRegion_IOT_EnergySaverManager_tev0_raised) {
		return SmartLightHUB_SmartLightHUB_SmartLightHubSystem_1_0_SmartLightsHUB_PowerConsumptionRegion_IOT_EnergySaverManager_time_event_0;
	}
	if(evid == &handle->timeEvents.smartLightHUB_SmartLightHubSystem_1_0_SmartLightsHUB_NetworkRegion_No_Connection_tev0_raised) {
		return SmartLightHUB_SmartLightHUB_SmartLightHubSystem_1_0_SmartLightsHUB_NetworkRegion_No_Connection_time_event_0;
	}
	if(evid == &handle->timeEvents.smartLightHUB_SmartLightHubSystem_1_0_SmartLightsHUB_NetworkRegion_Connected_tev0_raised) {
		return SmartLightHUB_SmartLightHUB_SmartLightHubSystem_1_0_SmartLightsHUB_NetworkRegion_Connected_time_event_0;
	}
	return SmartLightHUB_invalid_event;
}

